contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    fallback() external payable {
        payable(msg.sender).transfer(msg.value / 2);
    }

    function run(address target, uint value, bytes calldata data) public payable {
        require(address(this).balance >= value, "insufficient balance");

        uint targetBefore = target.balance;
        bool reverted;
        try c.sendMoney{value: value}(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint targetAfter = target.balance;
            uint returned = (value > targetAfter - targetBefore) ? (value - (targetAfter - targetBefore)) : 0;
            assert(address(c).balance == address(c).balance + value - returned - (returned > value ? returned - value : 0));
        }
    }
}

