contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Set up so that msg.sender is not the owner: the test contract calls C.
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt a deposit as non-owner. The fallback has no owner restriction,
        // so it should succeed and increase depositsCount.
        (bool okFallback, ) = address(c).call{value: amount}("");

        // Attempt owner-only state-changing calls as non-owner; each must revert.
        bool revertedWithdrawAll;
        try c.withdrawAll() { revertedWithdrawAll = false; } catch { revertedWithdrawAll = true; }
        bool revertedWithdraw;
        try c.withdraw(0) { revertedWithdraw = false; } catch { revertedWithdraw = true; }
        bool revertedSend;
        try c.sendMoney(address(this), 0, "") { revertedSend = false; } catch { revertedSend = true; }

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // For all inputs: non-owner fallback deposit succeeds, so depositsCount increases by exactly 1
        // and the contract balance increases by exactly amount; all owner-only functions revert
        // and therefore cannot change the balance.
        assert(
            okFallback
            && afterCount == beforeCount + 1
            && afterBalance == beforeBalance + amount
            && revertedWithdrawAll
            && revertedWithdraw
            && revertedSend
        );
    }
}

