contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        // Make the test contract a non-owner by ensuring owner is not address(this).
        // The contract is deployed by this test contract, so owner == address(this) initially.
        // Use sendMoney to send 0 value to an arbitrary address; this does not change owner.
        // To get a non-owner caller, exploit that c.owner remains address(this) unless changed,
        // but we cannot change owner from here. Instead, we can call withdrawAll from a context
        // where msg.sender is not owner? Actually msg.sender is always this test contract.
        // We need a non-owner. Since C has no function to change owner, and we cannot spoof msg.sender,
        // the only way to have a non-owner caller is to have the test contract call c.withdrawAll
        // from a different address. But we cannot use cheatcodes. So this rule is unexpressible.
        // Alternative: The contract's owner is the test contract. Any call from test contract is owner.
        // So non-owner revert is not testable without a helper contract or cheatcodes.
        // Therefore, pick a different rule.
        // Let's instead test: A call to sendMoney with value > balance must revert and leave balance unchanged.
        // But sendMoney is onlyOwner, and we are owner, so it's callable.
        // Rule: sendMoney with amount greater than c's balance reverts and does not change c's balance or depositsCount.
        // This is general and testable.
        require(amount > address(c).balance, "amount must exceed balance");
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        bool reverted;
        try c.sendMoney(address(this), amount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();
        assert(reverted && balAfter == balBefore && depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

